def validar_senha(senha):
    problemas = []
    if len(senha) < 8:
        problemas.append('curta')
    tem_numero = False
    tem_maiuscula = False
    for c in senha:
        if c.isdigit():
            tem_numero = True
        if c.isupper():
            tem_maiuscula = True
    if not tem_numero:
        problemas.append('sem número')
    if not tem_maiuscula:
        problemas.append('sem maiúscula')
    return problemas


def test_senha_boa():
    assert validar_senha('Python2026') == []


def test_senha_curta():
    assert validar_senha('Py1') == ['curta']


def test_sem_numero():
    assert validar_senha('PythonLegal') == ['sem número']


def test_sem_maiuscula():
    assert validar_senha('python2026') == ['sem maiúscula']
